/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailLoyaltyCardLoyaltyEnrollmentTime extends UPSPricingAttributeRetailLoyaltyCard implements UPSIPricingAttribute
{
}

