public str getName()
{
    return fieldPName(RetailLoyaltyCard, LoyaltyEnrollmentTime);
}

public Set getAllowedValues()
{
    RetailLoyaltyCard   retailLoyaltyCard;
    var                 ret = new Set(Types::Time);

    while select LoyaltyEnrollmentTime from retailLoyaltyCard
        group by LoyaltyEnrollmentTime
    {
        ret.add(retailLoyaltyCard.LoyaltyEnrollmentTime);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailLoyaltyCard, LoyaltyEnrollmentTime));
    qbr.value(queryValue(_value));
}
